#!/usr/bin/env python3
"""
Config for build and install scripts
"""

from pathlib import Path

BASE_PATH = Path(__file__).parent.absolute()

# Where to find stock dump, which will be used as a basis for the debian image
EXISTING_DUMP_NAME = 'stock_dump'
EXISTING_DUMP = BASE_PATH.joinpath('dumps').joinpath(EXISTING_DUMP_NAME)

# Network
HOST_NAME = 'superbird'
USBNET_PREFIX = '192.168.7'  # usb network will use .1 as host device, and .2 for superbird

# User info
USER_NAME = 'superbird'
# Password login is locked in new images.
USER_PASS_HASH = '!'  # New images accept a caller-supplied public key only.

# config for debootstrap
ARCHITECTURE = 'arm64'
DISTRO_REPO_URL = 'http://deb.debian.org/debian/'
DISTRO_BRANCH = 'bullseye'
DISTRO_VARIANT = 'minbase'

# you can add extra packages here to install during stage 2
#   will be installed like this (in chroot): apt install -y --no-install-recommends --no-install-suggests {EXTRA_PACKAGES}
EXTRA_PACKAGES = ''

# timezone and locale
TIMEZONE = 'America/Los_Angeles'
LOCALE = 'en_US.UTF-8'


# SSH keys
#   NOTE: this key is ONLY used between the host and superbird, via the usb network.



LEGACY_SSH_PUBLIC_KEY = 'ssh-rsa  superbird@host'


def export_config():
    # HACK export most vars so we can use this for bash too
    TEMPFILE = '/tmp/config.sh'
    if Path(TEMPFILE).is_file():
        Path(TEMPFILE).unlink()
    EXPORTED_VARS: list[str] = [
        'EXISTING_DUMP_NAME', 'EXISTING_DUMP', 'HOST_NAME', 'USBNET_PREFIX', 'USER_NAME', 'TIMEZONE', 'LOCALE'
    ]
    _lines: list[str] = []
    _lines.append('# auto-generated by config.py')
    for var in EXPORTED_VARS:
        value = globals()[var]
        _lines.append(f'{var}="{value}"')
    _lines.append('')
    _content = '\n'.join(_lines)
    with open(TEMPFILE, 'wt', encoding='utf-8') as cf:
        cf.write(_content)
    print(TEMPFILE)


if __name__ == '__main__':
    export_config()
